// WP-104 d1 / SE-121: Korean verb forms generated by a Hangul-aware conjugator (jamo arithmetic on syllable blocks).
// Authored from the author's own knowledge; no external morphology data.
// Handles: vowel harmony (아/어), vowel contraction (ㅏ+아, ㅗ+아->ㅘ, ㅜ+어->ㅝ, ㅣ+어->ㅕ, ㅚ+어->ㅙ, ...), 하->해/했,
// ㅡ-dropping, and the irregular classes ㅂ ㄷ ㅅ ㄹ(dropping) 르 우, plus honorific 시-verbs. Forms are single space-less tokens.
// Verbs only (no adjectives). 하다/되다 compounds are generated as single tokens (공부합니다, 사용했어요 ...).
//
// Stem table entry: "stem" or "stem:flag"   flags: b ㅂ-irregular, d ㄷ-irregular, s ㅅ-irregular, r 르-irregular, u 우-irregular
// (푸다), st stative (있다 없다: no imperative/propositive/ㄴ-adnominal), hon honorific-supplete (계시다 ...: 계세요), o 놓-type (놔).

const BASE = 0xac00;
const dec = (ch) => { const c = ch.codePointAt(0) - BASE; return { l: Math.floor(c / 588), v: Math.floor((c % 588) / 28), t: c % 28 }; };
const comp = (l, v, t = 0) => String.fromCodePoint(BASE + (l * 21 + v) * 28 + t);
const isHangul = (ch) => { const c = ch.codePointAt(0); return c >= 0xac00 && c <= 0xd7a3; };

// lead (choseong) indices
const L_R = 5, L_P = 17, L_O = 11, L_H = 18, L_N = 2, L_S = 9;
// vowel (jungseong) indices
const V_A = 0, V_AE = 1, V_YA = 2, V_EO = 4, V_E = 5, V_YEO = 6, V_O = 8, V_WA = 9, V_WAE = 10, V_OE = 11, V_YO = 12,
  V_U = 13, V_WO = 14, V_WI = 16, V_EU = 18, V_UI = 19, V_I = 20;
// trail (jongseong) indices
const T_N = 4, T_L = 8, T_M = 16, T_B = 17, T_SS = 20;

const withT = (s, t) => { const d = dec(s.at(-1)); return s.slice(0, -1) + comp(d.l, d.v, t); };
const dropT = (s) => withT(s, 0);
const lastT = (s) => dec(s.at(-1)).t;
const bright = (v) => v === V_A || v === V_YA || v === V_O || v === V_WA || v === V_YO; // yang vowels -> 아

function mkInfo(spec) {
  const [stem, flag = ""] = spec.split(":");
  const d = dec(stem.at(-1));
  const info = { orig: stem, eff: stem, eu: false, lStem: false, cls: "reg", flag };
  if (flag === "b") { info.cls = "b"; info.eff = dropT(stem) + "우"; }
  else if (flag === "d") { info.cls = "d"; info.eff = withT(stem, T_L); info.eu = true; }
  else if (flag === "s") { info.cls = "s"; info.eff = dropT(stem); info.eu = true; }
  else if (flag === "r") { info.cls = "reu"; }
  else if (flag === "u") { info.cls = "u"; }
  else if (d.l === L_H && d.v === V_A && d.t === 0) info.cls = "ha";
  else if (d.v === V_EU && d.t === 0) info.cls = "eu";
  else if (d.t === T_L) info.lStem = true;
  if (info.cls === "reg" && !info.lStem && d.t !== 0) info.eu = true;
  info.st = flag === "st";
  info.hon = flag === "hon";
  if (flag === "o") info.alt = mkInfo(dropT(stem));
  return info;
}

// vowel-join: stem + 아/어 (+ optional ㅆ) + rest, with contraction. Returns an array of spellings.
function vj(info, ss, rest) {
  const tt = ss ? T_SS : 0;
  const s = info.orig;
  const d = dec(s.at(-1));
  const res = [];
  const push = (x) => res.push(x + rest);
  switch (info.cls) {
    case "ha": {
      const base = s.slice(0, -1);
      push(base + comp(L_H, V_AE, tt));
      push(base + "하" + comp(L_O, V_YEO, tt));
      break;
    }
    case "b": {
      const base = dropT(s);
      push(base + comp(L_O, d.v === V_O ? V_WA : V_WO, tt));
      break;
    }
    case "d":
      push(withT(s, T_L) + comp(L_O, bright(d.v) ? V_A : V_EO, tt));
      break;
    case "s": {
      const base = dropT(s);
      push(base + comp(L_O, bright(dec(base.at(-1)).v) ? V_A : V_EO, tt));
      break;
    }
    case "reu": {
      const prev = dec(s.at(-2));
      push(s.slice(0, -2) + comp(prev.l, prev.v, T_L) + comp(L_R, bright(prev.v) ? V_A : V_EO, tt));
      break;
    }
    case "u":
      push(s.slice(0, -1) + comp(d.l, V_EO, tt));
      break;
    case "eu": {
      const prev = s.length >= 2 ? dec(s.at(-2)) : null;
      push(s.slice(0, -1) + comp(d.l, prev && bright(prev.v) ? V_A : V_EO, tt));
      break;
    }
    default:
      if (d.t !== 0) { push(s + comp(L_O, bright(d.v) ? V_A : V_EO, tt)); break; }
      // vowel-final regular stem
      {
        const head = s.slice(0, -1);
        const unc = s + comp(L_O, bright(d.v) ? V_A : V_EO, tt);
        const c = (v) => head + comp(d.l, v, tt) + "";
        if (bright(d.v)) {
          if (d.v === V_A) push(c(V_A));
          else if (d.v === V_O) { push(c(V_WA)); if (d.l !== L_O) push(unc); }
          else push(unc);
        } else if (d.v === V_EO) push(c(V_EO));
        else if (d.v === V_U) { push(c(V_WO)); if (d.l !== L_O) push(unc); }
        else if (d.v === V_I) { push(c(V_YEO)); push(unc); }
        else if (d.v === V_AE) push(c(V_AE));
        else if (d.v === V_E) push(c(V_E));
        else if (d.v === V_YEO) push(c(V_YEO));
        else if (d.v === V_OE) { push(c(V_WAE)); push(unc); }
        else push(unc); // ㅟ ㅢ ㅠ ...: 쉬어 뛰어 띄어
      }
  }
  if (info.alt) res.push(...vj(info.alt, ss, rest));
  return res;
}

const initialL = (str) => (isHangul(str[0]) ? dec(str[0]).l : -1);

// consonant-initial endings attach to the dictionary stem (ㄹ drops before ㄴ)
function cons(info, e) {
  const base = info.lStem && initialL(e) === L_N ? dropT(info.orig) : info.orig;
  return base + e;
}
// 으-endings: 으 appears after consonant-final stems (not ㄹ-stems); ㄹ drops before ㄴ and ㅅ
function euAdd(info, e) {
  let base = info.eff;
  const il = initialL(e);
  if (info.lStem && (il === L_N || il === L_S)) base = dropT(base);
  return base + (info.eu && !info.lStem ? "으" : "") + e;
}
// batchim endings: (으)ㄴ (으)ㄹ (으)ㅁ (스)ㅂ니다 ...
function attachT(info, which, t, rest) {
  const s = which === "orig" ? info.orig : info.eff;
  const o = info.orig;
  if (info.lStem) {
    if (t === T_L) return o + rest;
    return withT(dropT(o), t) + rest;
  }
  const open = lastT(s) === 0 && !(info.eu && which === "eff");
  if (open) return withT(s, t) + rest;
  const syl = t === T_N ? "은" : t === T_L ? "을" : t === T_M ? "음" : rest.startsWith("니") ? "습" : "읍";
  return s + syl + rest;
}

const VJ_PRES = ["", "요", "서", "도", "야", "라", "야지"];
const VJ_PAST = ["다", "어", "어요", "습니다", "습니까", "는데", "고", "지만", "으면", "으니까", "으며", "던", "지", "지요", "죠", "네요",
  "군요", "더라", "더니", "을까요", "다가", "거든요", "잖아요", "을"];
const C_END = ["고", "지", "지만", "지요", "죠", "자", "기", "게", "겠다", "겠어요", "겠어", "겠습니다", "겠습니까", "겠지", "겠네요",
  "네", "네요", "는", "는데", "는지", "는군요", "도록", "다가", "자마자", "거나", "거든요", "잖아요", "고서", "고요", "길래", "던"];
const HON = ["세요", "십시오", "십니다", "십니까", "시는", "시고", "시면", "셔서", "셨다", "셨어요", "셨습니다", "셨는데", "시지만", "시죠", "시니까", "실", "신"];
const U_END = ["면", "니까", "려고", "러", "며", "면서"];

function conjugate(info, out) {
  const add = (x) => out.add(x);
  const st = info.st;
  add(info.orig + "다");
  for (const r of VJ_PRES) { if (st && (r === "라")) continue; for (const x of vj(info, false, r)) add(x); }
  for (const r of VJ_PAST) for (const x of vj(info, true, r)) add(x);
  for (const e of C_END) { if (st && (e === "자" || e === "자마자")) continue; add(cons(info, e)); }
  const ender = st ? U_END.filter((e) => e !== "러" && e !== "려고") : U_END;
  for (const e of ender) add(euAdd(info, e));
  if (!st) {
    if (info.hon) { const base = info.orig.slice(0, -1); for (const h of HON) add(base + h); }
    else for (const h of HON) add(euAdd(info, h));
  }
  // batchim endings
  if (!st) add(attachT(info, "eff", T_N, ""));
  add(attachT(info, "eff", T_L, ""));
  add(attachT(info, "eff", T_M, ""));
  for (const r of ["게요", "까요", "래요", "게", "까", "지", "수록"]) add(attachT(info, "eff", T_L, r));
  add(attachT(info, "orig", T_B, "니다"));
  add(attachT(info, "orig", T_B, "니까"));
  if (!st) add(attachT(info, "eff", T_B, "시다"));
  // plain present declarative: 간다 / 먹는다 / 안다
  if (!st) {
    if (info.lStem) add(withT(dropT(info.orig), T_N) + "다");
    else if (lastT(info.orig) === 0) add(withT(info.orig, T_N) + "다");
    else add(info.orig + "는다");
  }
  // 아/어서 forms already in VJ_PRES; 아/어 + 있다 etc. are separate words
}

const PLAIN = `
가 오 보 주 사 자 서 타 나 만나 건너 내 보내 가르치 마시 기다리 지키 배우 쉬 뛰 차 켜 깨 지내 세우 비우 태우 키우
되 드리 계시:hon 주무시:hon 드시:hon 잡수시:hon 놀라 이기 지 피우 남기 바꾸 끝내 끝나 보이 들리 걸리 열리 알리 살리 달리
올리 내리 놓치 맞추 돌리 시키 느끼 던지 만지 버리 떠나 일어나 태어나 돌아오 돌아가 들어가 들어오 나가 나오 올라가
내려가 가져오 가져가 찾아가 찾아보 알아보 살펴보 바라보 데려가 데려오 가지 기르:r
먹 입 읽 받 닫 믿 얻 잡 찍 씻 웃 벗 빼앗 찾 앉 넣 놓:o 닦 신 볶 맞 심 감 담 남 참 막 죽 묶 맡 뽑 씹 옮 닮 갖 앓 밟 짓:s
있:st 없:st
알 살 팔 만들 놀 열 들 걸 울 풀 돌 불 갈 날 떨 늘 줄 밀 물 썰 빨 벌 달 쓸
돕:b 눕:b 줍:b 굽:b
듣:d 묻:d 걷:d 싣:d 깨닫:d
낫:s 붓:s 잇:s 긋:s
모르:r 고르:r 부르:r 자르:r 흐르:r 오르:r 누르:r 바르:r 나르:r 서두르:r 마르:r 두르:r 가르:r 지르:r
푸:u
쓰 끄 모으 담그 잠그 따르 치르 들르 뜨 트 쏘
`;

// 하다 compounds (noun + 하다) and 되다 compounds (noun + 되다), written as single tokens
const HA_NOUNS = `
공부 운동 사용 이용 예약 구매 주문 문의 신청 등록 로그인 확인 검색 다운로드 설치 연락 결제 배송 취소 변경 선택 입력 제공
시작 준비 생각 사랑 이야기 전화 요리 청소 여행 운전 쇼핑 설명 소개 추천 방문 참여 참가 지원 관리 발송 전송 접속 가입
탈퇴 로그아웃 업로드 공유 저장 삭제 수정 업데이트 생성 인증 동의 거부 말 일 좋아 싫어 기억 대답 부탁 원 시도 계산 비교
확장 포함 제한 연결 해결 요청 처리 진행 완료 구독 판매 상담 문의 노력 조심 약속 결정 이해 해석 운영 개발 설계 제작
`;
const DOEN_NOUNS = `
완료 연결 시작 변경 선택 포함 사용 이용 제공 발생 지원 등록 저장 삭제 확인 진행 구성 운영 개발 준비 결정 취소 예약 해결 발표 공개
`;

export default function forms() {
  const out = new Set();
  for (const spec of PLAIN.split(/\s+/).filter(Boolean)) conjugate(mkInfo(spec), out);
  conjugate(mkInfo("하"), out);
  for (const n of HA_NOUNS.split(/\s+/).filter(Boolean)) conjugate(mkInfo(n + "하"), out);
  for (const n of DOEN_NOUNS.split(/\s+/).filter(Boolean)) conjugate(mkInfo(n + "되"), out);
  // Single-syllable forms collide with particles and common nouns (가 는 도 돈 달 물 문 ...): keep only the contracted
  // forms that are unmistakably verbs.
  const KEEP1 = new Set(["해", "봐", "줘", "써", "꺼", "켜", "퍼", "져", "쏴", "놔", "돼"]);
  return [...out].filter((w) => [...w].length > 1 || KEEP1.has(w));
}
